<?php
namespace qqworld_collector\module\translate; use qqworld_collector\lib; class Youdao extends lib { const URL = 'http://openapi.youdao.com/api'; const CURL_TIMEOUT = 15; public function __construct($appKey='', $appSecret='') { $this->appKey = $appKey; $this->appSecret = $appSecret; } public function translate($query, $from, $to) { $args = array( 'q' => $query, 'appKey' => $this->appKey, 'salt' => rand(10000, 99999), 'from' => $from, 'to' => $to, ); $args['sign'] = $this->buildSign($this->appKey, $query, $args['salt'], $this->appSecret); $ret = $this->call(self::URL, $args); $ret = json_decode($ret, true); if ($ret['errorCode'] == 0) { return $ret['translation'][0]; } else { return false; } } public function buildSign($appKey, $query, $salt, $secKey) { $str = $appKey . $query . $salt . $secKey; $ret = md5($str); return $ret; } public function call($url, $args=null, $method="post", $testflag = 0, $timeout = self::CURL_TIMEOUT, $headers=array()) { $ret = false; $i = 0; while($ret === false) { if($i > 1) break; if($i > 0) { sleep(1); } $ret = $this->callOnce($url, $args, $method, false, $timeout, $headers); $i++; } return $ret; } public function callOnce($url, $args=null, $method="post", $withCookie = false, $timeout = self::CURL_TIMEOUT, $headers=array()) { $ch = curl_init(); if($method == "post") { $data = $this->convert($args); curl_setopt($ch, CURLOPT_POSTFIELDS, $data); curl_setopt($ch, CURLOPT_POST, 1); } else { $data = $this->convert($args); if($data) { if(stripos($url, "?") > 0) { $url .= "&$data"; } else { $url .= "?$data"; } } } curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_TIMEOUT, $timeout); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); if(!empty($headers)) { curl_setopt($ch, CURLOPT_HTTPHEADER, $headers); } if($withCookie) { curl_setopt($ch, CURLOPT_COOKIEJAR, $_COOKIE); } $r = curl_exec($ch); curl_close($ch); return $r; } public function convert(&$args) { $data = ''; if (is_array($args)) { foreach ($args as $key=>$val) { if (is_array($val)) { foreach ($val as $k=>$v) { $data .= $key.'['.$k.']='.rawurlencode($v).'&'; } } else { $data .="$key=".rawurlencode($val)."&"; } } return trim($data, "&"); } return $args; } } ?>